SELECT
    concat(
        'https://ava.fiep.digital/course/view.php?id=',
        c.id
    ) as url,
    c.shortname,
    c.fullname,
    NULLIF(
        SPLIT_PART(SPLIT_PART(c.idnumber, '.', 2), '.', 1),
        ''
    ) :: int as numeroidentificacao,
    d.charvalue :: int as cargahoraria
FROM
    mdl_customfield_data d
    INNER JOIN mdl_customfield_field f ON f.id = d.fieldid
    INNER JOIN mdl_course c ON c.id = d.instanceid
WHERE f.shortname like 'carga_horaria' and c.id IN (
